-- ExamFlow institution server: database schema for Firebird 3+
-- Schema version 2. Run it connected to the EMPTY database (or schema) made for ExamFlow,
-- as its owner or an admin. Safe to run twice. Then give the ExamFlow user the rights listed in DATABASES.md.

-- Run with isql:  isql-fb -user SYSDBA -i firebird.sql localhost:/path/examflow.fdb   (the database must use UTF8)
SET TERM ^ ;

-- ── step 1 ──
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'meta')) THEN EXECUTE STATEMENT 'CREATE TABLE "meta" ("k" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "v" BLOB SUB_TYPE TEXT CHARACTER SET UTF8, PRIMARY KEY ("k"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'docs')) THEN EXECUTE STATEMENT 'CREATE TABLE "docs" ("col" VARCHAR(64) CHARACTER SET UTF8 NOT NULL, "id" VARCHAR(300) CHARACTER SET UTF8 NOT NULL, "data" BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, "created" BIGINT NOT NULL, "updated" BIGINT NOT NULL, f_examToken VARCHAR(255) CHARACTER SET UTF8, f_teacherUid VARCHAR(255) CHARACTER SET UTF8, f_switchCode VARCHAR(255) CHARACTER SET UTF8, PRIMARY KEY ("col", "id"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'users')) THEN EXECUTE STATEMENT 'CREATE TABLE "users" ("uid" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "email" VARCHAR(320) CHARACTER SET UTF8 NOT NULL, "name" VARCHAR(1000) CHARACTER SET UTF8, "pass_hash" VARCHAR(1000) CHARACTER SET UTF8, "source" VARCHAR(32) CHARACTER SET UTF8 NOT NULL, "oidc_sub" VARCHAR(1000) CHARACTER SET UTF8, "created" BIGINT NOT NULL, "disabled" INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY ("uid"), UNIQUE ("email"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'codes')) THEN EXECUTE STATEMENT 'CREATE TABLE "codes" ("code_hash" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "email" VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, "purpose" VARCHAR(32) CHARACTER SET UTF8 NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, "used" BIGINT, PRIMARY KEY ("code_hash"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'logins')) THEN EXECUTE STATEMENT 'CREATE TABLE "logins" ("token_hash" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "uid" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, PRIMARY KEY ("token_hash"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'oidc_state')) THEN EXECUTE STATEMENT 'CREATE TABLE "oidc_state" ("state" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "nonce" VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, "verifier" VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, "created" BIGINT NOT NULL, PRIMARY KEY ("state"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'allowlist')) THEN EXECUTE STATEMENT 'CREATE TABLE "allowlist" ("teacher_id" VARCHAR(191) CHARACTER SET UTF8 NOT NULL, "email" VARCHAR(320) CHARACTER SET UTF8 NOT NULL, "name" VARCHAR(1000) CHARACTER SET UTF8, "version" INTEGER NOT NULL, PRIMARY KEY ("teacher_id"), UNIQUE ("email"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'allowlist_history')) THEN EXECUTE STATEMENT 'CREATE TABLE "allowlist_history" ("n" BIGINT GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "package_id" VARCHAR(1000) CHARACTER SET UTF8, "package_version" VARCHAR(1000) CHARACTER SET UTF8, "list_version" INTEGER, "added" INTEGER, "removed" INTEGER, "total" INTEGER, PRIMARY KEY ("n"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'audit')) THEN EXECUTE STATEMENT 'CREATE TABLE "audit" ("n" BIGINT GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "actor" VARCHAR(1000) CHARACTER SET UTF8, "action" VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, "target" BLOB SUB_TYPE TEXT CHARACTER SET UTF8, "result" VARCHAR(1000) CHARACTER SET UTF8 NOT NULL, "detail" BLOB SUB_TYPE TEXT CHARACTER SET UTF8, PRIMARY KEY ("n"))'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$indices WHERE rdb$index_name = 'DOCS_EXAMTOKEN')) THEN EXECUTE STATEMENT 'CREATE INDEX docs_examToken ON "docs" ("col", f_examToken)'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$indices WHERE rdb$index_name = 'DOCS_TEACHERUID')) THEN EXECUTE STATEMENT 'CREATE INDEX docs_teacherUid ON "docs" ("col", f_teacherUid)'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$indices WHERE rdb$index_name = 'DOCS_SWITCHCODE')) THEN EXECUTE STATEMENT 'CREATE INDEX docs_switchCode ON "docs" ("col", f_switchCode)'; END ^
COMMIT ^
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$indices WHERE rdb$index_name = 'DOCS_CREATED')) THEN EXECUTE STATEMENT 'CREATE INDEX docs_created ON "docs" ("col", "created")'; END ^
COMMIT ^
-- append-only protection for the audit log (audit_no_change)
CREATE OR ALTER EXCEPTION audit_append_only 'the audit log is append-only' ^
COMMIT ^
GRANT USAGE ON EXCEPTION audit_append_only TO PUBLIC ^
COMMIT ^
CREATE OR ALTER TRIGGER audit_no_change FOR "audit" ACTIVE BEFORE UPDATE OR DELETE POSITION 0 AS BEGIN EXCEPTION audit_append_only; END ^
COMMIT ^

-- ── step 2 ──
EXECUTE BLOCK AS BEGIN IF (NOT EXISTS (SELECT 1 FROM rdb$relations WHERE rdb$relation_name = 'inbox')) THEN EXECUTE STATEMENT 'CREATE TABLE "inbox" ("msg_id" VARCHAR(64) CHARACTER SET UTF8 NOT NULL, "email" VARCHAR(254) CHARACTER SET UTF8 NOT NULL, "delivered_at" BIGINT, "read_at" BIGINT, "archived_at" BIGINT, PRIMARY KEY ("msg_id", "email"))'; END ^
COMMIT ^

-- record which schema version this database has
UPDATE OR INSERT INTO "meta" ("k", "v") VALUES ('schema_version', '2') MATCHING ("k") ^
COMMIT ^

COMMIT ^
SET TERM ; ^
